#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;
int currentAngle = 0;
int directionFlag = 1;  

void setup();
void loop();
void updateServos(int angle);
void updateLEDs(int numLeds);
void setup() {
  servo1.attach(2);  
  servo2.attach(3);  
  servo3.attach(4);  
  for (int pin = 5; pin <= 14; pin++) {  
    pinMode(pin, OUTPUT);
  }
  updateServos(0);
  updateLEDs(0);
}
void loop() {
  delay(2000);
  currentAngle += 18 * directionFlag;
  if (currentAngle >= 180 || currentAngle <= 0) {
    directionFlag *= -1;
  }
  currentAngle = constrain(currentAngle, 0, 180);
  updateServos(currentAngle);
  int total = currentAngle * 3;
  int leds = total / 54;
  updateLEDs(leds);
}
void updateServos(int angle) {
  servo1.write(angle);
  servo2.write(angle);
  servo3.write(angle);
}
void updateLEDs(int numLeds) {
  numLeds = constrain(numLeds, 0, 10);
  for (int i = 5; i <= 14; i++) {  
    digitalWrite(i, (i - 5) < numLeds ? HIGH : LOW);
  }
}
